CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, subject text NOT NULL UNIQUE, name text NOT NULL, admin boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS challenges (id text PRIMARY KEY, creator_id text NOT NULL REFERENCES users(id), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 80), description text NOT NULL CHECK(length(description) BETWEEN 1 AND 2000), category text NOT NULL CHECK(category IN ('Cleanup','Planting','Recycling','Conservation')), requirements jsonb NOT NULL, deadline timestamptz, status text NOT NULL DEFAULT 'published' CHECK(status IN ('published','closed')), hidden boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contributions (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id), challenge_id text NOT NULL REFERENCES challenges(id), latest_version integer NOT NULL DEFAULT 0, outcome text CHECK(outcome IN ('supported','needs_more_evidence','not_supported')), consent boolean NOT NULL DEFAULT false, consent_at timestamptz, hidden boolean NOT NULL DEFAULT false, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT one_contribution_per_member_challenge UNIQUE(owner_id,challenge_id));
CREATE TABLE IF NOT EXISTS uploads (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('result','before')), object_key text NOT NULL UNIQUE, derivative_key text, mime text, bytes integer, checksum text, state text NOT NULL DEFAULT 'allocated' CHECK(state IN ('allocated','ready','used','deleted')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_versions (id text PRIMARY KEY, contribution_id text NOT NULL REFERENCES contributions(id), version integer NOT NULL, description text NOT NULL CHECK(length(description) BETWEEN 1 AND 2000), requirements jsonb NOT NULL, result_upload_id text NOT NULL UNIQUE REFERENCES uploads(id), before_upload_id text UNIQUE REFERENCES uploads(id), accepted_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT immutable_evidence_version UNIQUE(contribution_id,version));
CREATE TABLE IF NOT EXISTS assessment_jobs (id text PRIMARY KEY, evidence_id text NOT NULL UNIQUE REFERENCES evidence_versions(id), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','processing','completed','failed')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, request_id text, error text, retry_at timestamptz, scenario text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assessments (id text PRIMARY KEY, evidence_id text NOT NULL REFERENCES evidence_versions(id), request_id text NOT NULL UNIQUE, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rewards (id text PRIMARY KEY, contribution_id text NOT NULL UNIQUE REFERENCES contributions(id), owner_id text NOT NULL REFERENCES users(id), assessment_id text NOT NULL REFERENCES assessments(id), amount integer NOT NULL DEFAULT 50 CHECK(amount=50), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS rewards_owner ON rewards(owner_id);
CREATE TABLE IF NOT EXISTS reports (id text PRIMARY KEY, reporter_id text NOT NULL REFERENCES users(id), target_id text NOT NULL, target_type text NOT NULL CHECK(target_type IN ('challenge','contribution')), reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_actions (id text PRIMARY KEY, admin_id text NOT NULL REFERENCES users(id), target_id text NOT NULL, target_type text NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, count integer NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS zyvara_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
INSERT INTO zyvara_migrations(name) VALUES('0001_initial') ON CONFLICT DO NOTHING;
